def GetVmodlValue(value):
   """ Get value from vmodl """

   if type(value) is int or type(value) is float:
      return value
   elif type(value) is bool:
      return 'true' if value else 'false'
   elif type(value) is str:
      return '\"%s\"' % value
   elif type(value) is list:
      return '[' + ','.join([GetVmodlValue(item) for item in value]) + ']'
   elif type(value) is dict:
      return '[' + ','.join(['%s:%s' % (key, GetVmodlValue(value[key])) for key in value]) + ']'

   raise Exception('Unknown type %s' % type(value))

def GetVmodlTypeAndValue(value):
   """ Get type and value from vmodl """

   return '%s,%s' % (GetVmodlType(value), GetVmodlValue(value))

